using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Numerics;
using System.Text.RegularExpressions;
using Fanex.Tarus.Infrastructure.Caching;
using Sunplus.Accounting.Core.Common;
using Sunplus.Accounting.Core.Configurations;
using Sunplus.Accounting.Core.Helper.IP;
using Sunplus.Accounting.DataAccess;
using Sunplus.Accounting.Entities;

namespace Sunplus.Accounting.Business
{
    /// <summary>
    /// Utilities class for IP
    /// </summary>
    public static class IpManagement
    {
        private static IpRange _ipVNList;

        static IpManagement()
        {
            _ipVNList = IPVNList;
        }

        public static IpRange IPVNList
        {
            get
            {
                if (_ipVNList == null)
                {
                    try
                    {
                        _ipVNList = CacheHelper.Get<IpRange>("ipvnlist") as IpRange ?? IBCProvider.Utils.GetIPVN();
                    }
                    catch
                    {
                        _ipVNList = IBCProvider.Utils.GetIPVN();
                    }
                }

                return _ipVNList;
            }
            set
            {
                _ipVNList = value;
                CacheHelper.Set("ipvnlist", value, DateTime.Now.AddMinutes(WebSettings.CacheExpire));
            }
        }

        public static bool IsVNIP(string IP)
        {
            var isIpv6 = IsIPV6(IP);
            if (isIpv6)
            {
                var ipv6Number = ConvertIpv6ToNumber(IP);
                return IPVNList.Ipv6List.Any(ip => ip.FromNumber <= ipv6Number && ipv6Number <= ip.ToNumber);
            }

            double ipNumber = IP2Number(IP);
            return IPVNList.Ipv4List.Any(ip => ip.IPFrom <= ipNumber && ipNumber <= ip.IPTo);
        }

        public static bool IsVNIP(string IP, IpRange _listIPVN)
        {
            var isIpv6 = IsIPV6(IP);
            if (isIpv6)
            {
                var ipv6Number = ConvertIpv6ToNumber(IP);
                return _listIPVN.Ipv6List.Any(ip => ip.FromNumber <= ipv6Number && ipv6Number <= ip.ToNumber);
            }

            double ipNumber = IP2Number(IP);
            return _listIPVN.Ipv4List.Any(ip => ip.IPFrom <= ipNumber && ipNumber <= ip.IPTo);
        }        

        //Check input string is a valid IP4 format
        public static bool IsValidIP(string addr)
        {
            string pattern =
                @"^([1-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(\.([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])){3}$";
            var check = new Regex(pattern);
            bool valid = false;
            if (addr == "")
            {
                valid = false;
            }
            else
            {
                valid = check.IsMatch(addr, 0);
            }
            return valid;
        }

        //Replace VN IP with other one or empty string
        public static string ReplaceVNIP(string IP)
        {
            if (IsVNIP(IP))
            {
                if (AppSession.ViewIPVN || WebSettings.IPVNReplace == "1")
                    return IP;
                else
                    return WebSettings.IPVNReplace;
            }
            else
            {
                return IP;
            }
        }

        public static string ReplaceCountryName(string IP)
        {
            var ipManager = new IpManager();
            string countryName = ipManager.GetCountryNameByIp(IP);
            if (IsVNIP(IP))
            {
                if (AppSession.ViewIPVN || WebSettings.IPVNReplace == "1")
                    return countryName;
                else
                    return "-";
            }
            else
            {
                return countryName;
            }
        }

        public static string ReplaceVNIP(string IP, IpRange _IPVNList)
        {
            if (AppSession.ViewIPVN)
            {
                return IP;
            }
            else
            {
                if (IsVNIP(IP, _IPVNList))
                    return WebSettings.IPVNReplace == "1" ? IP : WebSettings.IPVNReplace;
                else
                    return IP;
            }
        }

        //Convert IP to nummber
        public static double IP2Number(string IP)
        {
            try
            {
                double longIP = 0;
                if (IsValidIP(IP))
                {
                    string[] sIP = IP.Split('.');
                    longIP = double.Parse(sIP[0]) * 16777216 + double.Parse(sIP[1]) * 65536 + double.Parse(sIP[2]) * 256 +
                             double.Parse(sIP[3]);
                }
                return longIP;
            }
            catch (Exception ex)
            {
                Sunplus.Accounting.Core.Extensions.LogExtensions.ExceptionHandler(ex);
                return 0.0;
            }
        }

        //Save IPVN table to Cache
        //Replace with your suitable cache
        //In this case we are using SharedCache: http://www.sharedcache.com/cms/

        public static string FormatIP(string ip)
        {
            return new AccountingIPFormat(ip).Format();
        }

        public static string FormatIPs(string content)
        {
            return new AccountingIPFormat("").FormatAll(content);
        }

        private static bool IsIPV6(string clientIP)
            => IPAddress.TryParse(clientIP, out IPAddress address)
                && address.AddressFamily == AddressFamily.InterNetworkV6;

        public static BigInteger ConvertIpv6ToNumber(string ipv6)
        {
            BigInteger bigInteger = 0;
            if (IPAddress.TryParse(ipv6, out IPAddress address))
            {
                byte[] numArray = address.GetAddressBytes();
                if (BitConverter.IsLittleEndian)
                {
                    List<byte> byteList = new List<byte>(numArray);
                    byteList.Reverse();
                    numArray = byteList.ToArray();
                }
                bigInteger = numArray.Length <= 8 ? BitConverter.ToUInt32(numArray, 0) : ((BigInteger)BitConverter.ToUInt64(numArray, 8) << 64) + BitConverter.ToUInt64(numArray, 0);
            }

            return bigInteger;
        }
    }
}